function matchControllerAction($url, $config) : string {
    $rules = $config['rules'];
    foreach ($rules as $pattern => $action) {
        if ($pattern === $url) {
            return $action;
        } elseif (strpos($pattern, '*') !== false) {
            $pattern = str_replace('*', '(.*)', $pattern);
            if (preg_match('#^' . $pattern . '$#', $url, $matches)) {
                return $action;
            }
        }
    }
    return 'default/index';
}
```

