/**
 * Processes a template file and returns a closure for rendering the template with a given set of environment variables.
 *
 * @param string $file The path to the template file
 * @return \Closure A closure for rendering the template
 * @throws IOException If the file is not found
 */
function processTemplate(string $file): \Closure {
    $file = \str_replace(["/", "\\"], DIRECTORY_SEPARATOR, $file);
    if($file[0] !== '/')
        $file = '/' . $file;
    /** @noinspection PhpUndefinedMethodInspection */
    $file = Configuration::TemplateDirectory() . $file;
    if(!\file_exists($file))
        throw new IOException("File " . $file . " not found.");
    $__template = $file;
    $contents = self::Compile(\file_get_contents($__template));
    return function (array $__env = []) use ($__template, $contents) {
        eval("unset(\$contents); extract(\$__env); ?> " . $contents . " <?php ");
    };
}
