class FormFieldHelper {
    private $fieldKey;
    private $errorCollection;
    private $attributes;

    public function __construct($fieldKey, $errorCollection, $attributes) {
        $this->fieldKey = $fieldKey;
        $this->errorCollection = $errorCollection;
        $this->attributes = $attributes;
    }

    public function getErrorMessages() {
        if ($this->errorCollection->has('default')) {
            $messageBag = $this->errorCollection->get('default');
            return $messageBag->get($this->fieldKey, []);
        }
        return [];
    }
}

// Usage example
