// PrimeNumber.php
use Symfony\Component\Validator\Constraint;

/**
 * @Annotation
 */
class PrimeNumber extends Constraint
{
    public $message = 'The number {{ value }} is not a prime number.';

    public function validatedBy()
    {
        return PrimeNumberValidator::class;
    }
}

// PrimeNumberValidator.php
use Symfony\Component\Validator\Constraint;
use Symfony\Component\Validator\ConstraintValidator;

class PrimeNumberValidator extends ConstraintValidator
{
    public function validate($value, Constraint $constraint)
    {
        if (!$this->isPrime($value)) {
            $this->context->buildViolation($constraint->message)
                ->setParameter('{{ value }}', $value)
                ->addViolation();
        }
    }

    private function isPrime($number)
    {
        if ($number <= 1) {
            return false;
        }
        for ($i = 2; $i <= sqrt($number); $i++) {
            if ($number % $i === 0) {
                return false;
            }
        }
        return true;
    }
}

// NumberEntity.php
use Symfony\Component\Validator\Constraints as Assert;

class NumberEntity
{
    /**
     * @Assert\NotBlank
     * @PrimeNumber
     */
    private $number;

    public function getNumber()
    {
        return $this->number;
    }

    public function setNumber($number)
    {
        $this->number = $number;
    }
}
```

In this solution, we define a custom constraint `PrimeNumber` that extends `Constraint` and specify the error message. We also define the `validatedBy` method to link the constraint to its validator class. The `PrimeNumberValidator` class implements the validation logic to check whether a number is prime or not. Finally, we apply the `PrimeNumber` constraint to the `number` property in the `NumberEntity` class to ensure it is validated as a prime number."}]

