class Restrictions
{
    private $minValue;
    private $maxValue;
    private $allowedTypes = [];
    private $customValidations = [];

    public function setMinValue($value)
    {
        $this->minValue = $value;
    }

    public function setMaxValue($value)
    {
        $this->maxValue = $value;
    }

    public function setAllowedTypes(array $types)
    {
        $this->allowedTypes = $types;
    }

    public function addCustomValidation(callable $validationFunction)
    {
        $this->customValidations[] = $validationFunction;
    }

    public function validate($value)
    {
        if ($this->minValue !== null && $value < $this->minValue) {
            return false;
        }

        if ($this->maxValue !== null && $value > $this->maxValue) {
            return false;
        }

        if (!empty($this->allowedTypes) && !in_array(gettype($value), $this->allowedTypes)) {
            return false;
        }

        foreach ($this->customValidations as $validation) {
            if (!$validation($value)) {
                return false;
            }
        }

        return true;
    }
}
