function rearrangeQueue($queue) {
    $length = count($queue);
    for ($i = 0; $i < $length; $i++) {
        for ($j = 0; $j < $length - 1 - $i; $j++) {
            if ($queue[$j] > $queue[$j + 1]) {
                // Swap the elements
                list($queue[$j], $queue[$j + 1]) = [$queue[$j + 1], $queue[$j]];
            }
        }
    }
    return $queue;
}

