```php
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\ParamConverter\ParamConverterInterface;
use Symfony\Component\HttpFoundation\ParamConverter\ParamConverter;

class UtcDateTimeConverter implements ParamConverterInterface
{
    public function convert(Request $request, ParamConverter $configuration)
    {
        $name = $configuration->getName();
        $segment = $request->attributes->get($name);
        if ($segment !== null) {
            if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $segment)) {
                $year = (int)substr($segment, 0, 4);
                $month = (int)substr($segment, 5, 2);
                $day = (int)substr($segment, 8, 2);
                $request->attributes->set($name, new UtcDateTime($year, $month, $day));
                return true;
            }
        }
        return false;
    }

    public function supports(ParamConverter $configuration): bool
    {
        return is_a($configuration->getClass(), DateTimeInterface::class, true);
    }
}
```"}]

