function parseAnnotations(string $class): array
{
    $reflectionClass = new ReflectionClass($class);
    $methods = $reflectionClass->getMethods();
    $result = [];

    foreach ($methods as $method) {
        $annotations = $method->getDocComment();
        preg_match('/@group\s+([^\s]+)/', $annotations, $matches);
        $group = isset($matches[1]) ? $matches[1] : 'No Group';
        $methodName = $method->getName();
        $result[$group][] = $methodName;
    }

    return $result;
}
```

