class MaxDifference
{
    public function findMaxDifference($arr)
    {
        $maxDiff = 0;
        $n = count($arr);

        for ($i = 0; $i < $n - 1; $i++) {
            for ($j = $i + 1; $j < $n; $j++) {
                if ($arr[$j] > $arr[$i]) {
                    $diff = $arr[$j] - $arr[$i];
                    if ($diff > $maxDiff) {
                        $maxDiff = $diff;
                    }
                }
            }
        }

        return $maxDiff;
    }
}
```

