use Illuminate\Http\JsonResponse;

class AppVerifyMiddleware
{
    protected $appsHandler;

    public function __construct(AppsHandler $appsHandler)
    {
        $this->appsHandler = $appsHandler;
    }

    public function handle($request, $next)
    {
        $appKey = $request->header('x-lk-sanmark-janus-app-key');
        $secretHash = $request->header('x-lk-sanmark-janus-app-secret-hash');

        if (!$appKey || !$secretHash) {
            return new JsonResponse(['error' => 'App key and secret hash are required'], 400);
        }

        if (!$this->appsHandler->isValidByKeyAndSecretHash($appKey, $secretHash)) {
