        return -1;
    }

    // Get the current date
    $currentDate = new \DateTime();

    // Create a DateTime object for the birthday
    $birthdayDate = new \DateTime(sprintf('%s-%s-%s', $birthdayYear, $birthdayMonth, $birthdayDay));

