<?php
// Function to check if a number is prime
function isPrime($n) {
    if ($n <= 1) {
        return false;
    }
    for ($i = 2; $i < $n; $i++) {
        if ($n % $i === 0) {
            return false;
        }
    }
    return true;
}

// Function to check if a number is in Fibonacci sequence
function isFibonacci($num) {
    $a = 0;
    $b = 1;
    if ($num === $a || $num === $b) {
        return true; 
    }
    $c = $a + $b;
    while ($c <= $num) {
        if ($c === $num) {
            return true;
        }
        $a = $b;
        $b = $c;
        $c = $a + $b;
    }
    return false;
}

// Function to find the n-th prime fibonacci number
function primeFib($n) {
    $primeFibNumbers = [];
    $i = 0;
    // Iterate till we find 'n' prime fibonacci numbers
    while (count($primeFibNumbers) < $n) {
        if (isPrime($i) && isFibonacci($i)) {
            array_push($primeFibNumbers, $i);
        }
        $i++;
    }
    // Return the n-th prime fibonacci number
    return $primeFibNumbers[$n - 1];
}
?>
