```php
function factorial($number) {
    // Check if number is a whole number
    if (!is_numeric($number) || round($number) != $number || $number < 0) {
        return "Error: Input must be a non-negative whole number.";
    }

    // If number is 0, its factorial is 1
    if ($number == 0) {
        return 1;
    }

    // Initial factorial value to be 1
    $factorial = 1;

    // Loop from the number to 1 and multiply each value to obtain the factorial
    for ($i = $number; $i > 0; $i--) {
        $factorial *= $i;
    }

    return $factorial;
}
```

To use this function, simply call it with the number you want to calculate the factorial of:

```php
echo factorial(5); // Outputs 120
echo factorial(-1); // Outputs "Error: Input must be a non-negative whole number."
echo factorial(0); // Outputs 1
```"}]

