    $distinct_absolute_sums = 0;              // initialize sum of distinct absolute values
    $distinct_elements = array();              // initialize an array to keep track of encountered distinct elements

    foreach ($arr as $n) {
        if($n == 0)                           // if the current number is 0, return NULL as per requirement
            return NULL;

        $absolute_value = abs($n);           // get absolute value of the current number

        if(in_array($absolute_value, $distinct_elements))   
            continue;                        // if this absolute value has been encountered before, ignore it

        array_push($distinct_elements, $absolute_value); // mark this absolute value as encountered

        $sign = $n/$absolute_value;          // calculate sign of the current number

        $distinct_signs_product *= $sign;    // update the product of distinct signs

        $distinct_absolute_sums += $absolute_value; // update the sum of distinct absolute values
    }

    return $distinct_signs_product*$distinct_absolute_sums; // return the product as per requirement
}
