function isPalindrome($string) {
    $left = 0;
    $right = strlen($string) - 1;

    while ($left < $right) {
        $leftChar = $string[$left];
        $rightChar = $string[$right];

        if (!ctype_alnum($leftChar)) {
            $left++;
            continue;
        }

        if (!ctype_alnum($rightChar)) {
            $right--;
            continue;
        }

        if (strcasecmp($leftChar, $rightChar) !== 0) {
            return false;
        }

        $left++;
        $right--;
    }

    return true;
}

