function displayPrimes($n) {
    // Iterate from 2 to n
    for ($i = 2; $i <= $n; $i++) {
        $isPrime = true;

        // Check if $i is divisible by any number between 2 and sqrt($i)
        for ($j = 2; $j <= sqrt($i); $j++) {
            if ($i % $j === 0) {
                $isPrime = false;
                break;
            }
        }

